def _scope_language(path: str) -> str:
    suffix = Path(path).suffix.lower()
    if suffix == ".py":
        return "py"
    if suffix in {".js", ".mjs", ".cjs", ".ts", ".tsx", ".jsx"}:
        return "js"
    return "module"


