def _assignment_operands(normalized: str) -> tuple[str, str] | None:
    """Split a real assignment; comparisons and arrows are not bindings."""
    masked = re.sub(
        r"===|!==|==|!=|<=|>=|=>",
        lambda match: " " * len(match.group(0)),
        normalized,
    )
    left, separator, right = masked.partition("=")
    if not separator:
        return None
    return left, right


